parameters.jsCode:
const properties = $input.first().json.properties || [];

const filtered = properties.filter(p => {
  // valid hotel হলে hotel_class অথবা rate_per_night থাকবে
  const hasValidPricing = p.rate_per_night && p.rate_per_night.lowest;
  const hasValidClass = p.hotel_class !== undefined;

  // suspicious keyword থাকলে বাদ দাও
  const suspiciousKeywords = ['dispensary', 'cannabis', 'weed', 'smoke shop', 'vape'];
  const nameHasSuspiciousWord = suspiciousKeywords.some(word => 
    (p.name || '').toLowerCase().includes(word)
  );

  return (hasValidPricing || hasValidClass) && !nameHasSuspiciousWord;
});

return [{ json: { properties: filtered } }];

